SELECT mode,count() AS answers,countIf(result='correct') AS correct,countIf(result='wrong') AS wrong,correct/nullIf(answers,0) AS correct_rate,avgOrNull(answer_time_ms)/1000 AS answer_seconds FROM knowledge_analytics.training_answers WHERE $__timeFilter(occurred_at) AND (${mode:sqlstring}='__all' OR mode=${mode:sqlstring}) AND (${algorithm:sqlstring}='__all' OR algorithm_version=${algorithm:sqlstring}) AND (${experiment:sqlstring}='__all' OR experiment_group=${experiment:sqlstring}) GROUP BY mode
